static inline void oss_vae_normalizza(const float *grezza, float *fuori)
{
    for (int i = 0; i < OSS_VAE_N; ++i) {
        float v = (grezza[i] - oss_vae_media[i]) * oss_vae_inv_scala[i];
        if (v >  OSS_VAE_CLIP) v =  OSS_VAE_CLIP;
        if (v < -OSS_VAE_CLIP) v = -OSS_VAE_CLIP;
        fuori[i] = v;
    }
}
